AVATAR_GRADIENTS = [
    ("#6366f1", "#a855f7"), ("#06b6d4", "#3b82f6"), ("#f59e0b", "#ef4444"), ("#10b981", "#06b6d4"),
    ("#ec4899", "#8b5cf6"), ("#f97316", "#eab308"), ("#14b8a6", "#22c55e"), ("#8b5cf6", "#3b82f6"),
]


@register.simple_tag
def icon(name, size=18, cls=""):
    body = ICONS.get(name, "")
    return mark_safe(
        f'<svg class="i {cls}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>'
    )


@register.simple_tag
def avatar(user, size=36):
    name = (user.get_full_name() or user.phone or "?").strip()
    initials = "".join(p[0] for p in name.split()[:2]).upper()
    a, b = AVATAR_GRADIENTS[(user.pk or 0) % len(AVATAR_GRADIENTS)]
    return format_html(
        '<span class="avatar" style="--s:{}px;background:linear-gradient(135deg,{},{})">{}</span>', size, a, b, initials)


@register.filter
def initial(value):
    return (str(value) or "?")[:1].upper()
